CREATE TABLE IF NOT EXISTS vervent.code_values (
  code_set    text NOT NULL,
  code        text NOT NULL,
  description text,
  definition  text,
  PRIMARY KEY (code_set, code)
);
COMMENT ON TABLE vervent.code_values IS 'Vervent/LeasePak code descriptions. Join with LEFT JOIN on (code_set, code); report tables carry codes the dictionary does not list.';
COMMENT ON COLUMN vervent.code_values.code_set IS 'One of: ls_status (contract_summary.ls_status, asset_summary.contr_status); asset_status (asset_summary.status); ls_type (contract_summary.ls_type, asset_summary.ls_type); accrual_method (contract_summary.accrual_method); late_code (contract_summary.late_code); use_tax_code (contract_summary.use_tax_code, asset_summary.tax_code); ls_source (contract_summary.ls_source); coll_code (contract_summary.coll_code); repo_code (asset_summary.curr_repo_status, asset_summary.repo_code); bank_code (transaction_history.bankcd); tran_code (transaction_history.trans)';

CREATE TABLE IF NOT EXISTS vervent.gl_vector (
  vector      integer PRIMARY KEY,
  gl_account  text,
  description text
);
COMMENT ON TABLE vervent.gl_vector IS 'General-ledger vectors referenced by transaction_history.debit_vector / credit_vector.';

ON CONFLICT (code_set, code) DO NOTHING;

ON CONFLICT (vector) DO NOTHING;
