INSERT INTO vervent.code_values (code_set, code, description, definition) VALUES
  ('ls_status', 'AA01', 'ACTIVE PRIOR CHARGE OFF, a previously terminated contract that has been reactivated. This status is entered through the Suspended Earnings update.', NULL),
  ('ls_status', 'AA02', 'ACTIVE PRIOR SKIP, the Obligor had previously absconded and placed in ‘HSKP'' or ‘NSKP'' status. The contract is active and will be tracked as a previous skip. This status is entered through the Suspended Earning update.', NULL),
  ('ls_status', 'AASM', 'ACTIVE ASSUMED, the contract was assumed by another obligor. System automatically assigns this status to the contract when assumed.', NULL),
  ('ls_status', 'AEXM', 'ACTIVE EXTENDED MONTH-TO-MONTH, The original contract matured and was extended month-to-month through the Contract Extension update. System automatically assigns this status to the contract when extended.', NULL),
  ('ls_status', 'AEXT', 'ACTIVE EXTENDED,the original contract matured and was extended for a specified term through the Contract Extension update. System automatically assigns this status to the contract when extended.', NULL),
  ('ls_status', 'ANOR', 'ACTIVE NORMAL, the contract is active under normal circumstances. System automatically assigns this status to the contract when booked. This status may also be entered through the Master Financial update.', NULL),
  ('ls_status', 'ABPT', 'ACTIVE BLOCK PAYMENTS, the contract is active and will continue to accrue to the general ledger accounts. Payments of any type may not be posted including: Payments, Batch Payments, and Assumed Payments, will not be allowed. In addition, Payoffs or Terminations, will not be allowed. The contract will not mature to ‘NMAT'' status. This status is entered through the Master Financial update.', NULL),
  ('ls_status', 'ARBK', 'REBOOK, the contract has been rebooked through the Rebook update. The Rebook update is used to change the initial booking information of the contract, such as the assets tied to the contract, payment schedule, commencement date, etc. System automatically assigns this status to the contract when rebooked.', NULL),
  ('ls_status', 'ARED', 'ACTIVE REDEMPTION, the repossessed contractd assets have been redeemed by the obligor and the contract has been reinstated. This status is entered through the Master Financial update.', NULL),
  ('ls_status', 'AREN', 'ACTIVE RENEGOTIATED, the contract terms have been renegotiated. This status is entered through the Master Financial update.', NULL),
  ('ls_status', 'AREP', 'ACTIVE ASSIGNED FOR REPOSSESSION, the contractd assets are assigned for repossession, but have not yet been recovered. contract payments may not be processed for a contract with this status. This status is entered through the Master Financial update.', NULL),
  ('ls_status', 'AXFR', 'ACTIVE TRANSFERRED, the contract has been transferred from one accounting unit (portfolio, company, region, and office) to another through the Change contract Key update. System automatically assigns this status to the contract when it is moved to another accounting unit.', NULL),
  ('ls_status', 'HHLD', 'NON-ACCRUAL HOLD, the income earnings are not accrued for the contract for a non-specific reason. This status is entered through the Suspended Earnings update.', NULL),
  ('ls_status', 'HINS', 'NON-ACCRUAL NON-INSURANCE, the income earnings are not accrued for the contract due to lack of adequate and/or required insurance. This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'HREC', 'NON-ACCRUAL RESCISSION, the income earnings are not accrued for the contract because the lessee has rescinded on the contract contract. This status is entered through the Suspended Earnings update.', NULL),
  ('ls_status', 'HREP', 'NON-ACCRUAL INVOLUNTARY REPOSSESSION, the income earnings are not accrued for the contract because the contractd assets have been repossessed by the lessor. This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'HSET', 'NON-ACCRUAL INSURANCE SETTLEMENT, the income earnings are not accrued for the contract because an insurance settlement is pending (i.e., the assets have been damaged or destroyed). This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'HSKP', 'NON-ACCRUAL SKIP, the income earnings are not accrued for the contract because the lessee absconded with the contractd assets. This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'HVOL', 'NON-ACCRUAL VOLUNTARY REPOSSESSION, the income earnings are not accrued for the contract because the lessee desires to return the contractd assets to the lessor in order to terminate the contract contract. This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'NCRP', 'CHARGE OFF: INVOLUNTARY REPOSESSION, the contract has been charged off due to involuntary repossession of the contractd assets. The contract is no longer active. System automatically assigns this status to the contract when the contract is paid off (through the Payoff update) with an activity status of.', NULL),
  ('ls_status', 'NREP', 'NON- ACCRUAL INVENTORY REPOSSESSION, (suspended earnings-assigned for repossession). Note that this status is not assigned if the activity status is ‘AREP'' (active assigned for repossession). / SUSPENDED EARNINGS INVOLUNTARY REPOSSESSION, the income earnings are suspended for the contractbecause the financed assets have been repossessed by the lender/lessor. This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'NCSK', 'CHARGE OFF: SKIP, the contract has been charged off due to a obligor skip (i.e., the obligor absconded with the contractd assets). The contract is no longer active. System automatically assigns this status to the contract when the contract is paid off (through the Payoff update) with an activity status of ‘NSKP'' (suspended earnings skip).', NULL),
  ('ls_status', 'NP01', 'CHARGE OFF: FORECLOSURE, the contract has been Charged off due to foreclosure. The contract is no longer active. This status is entered through the Suspended Earnings update. Note that this status is assigned if the activity status is NH01 (suspended earnings foreclosure).', NULL),
  ('ls_status', 'NP04', 'CHARGE OFF: WRITE OFF, the contract has been charged off as a write off. The contract is no longer active. This status is entered through the Suspended Earnings update. Note that this status is assigned if the activity status is NH04 (suspended earnings write off).', NULL),
  ('ls_status', 'NCVL', 'CHARGE OFF: VOLUNTARY REPOSSESSION, the contract has been charged off due to voluntary repossession (i.e., the obligor voluntarily returns the contractd assets in order to terminate the contract). The contract is no longer active. System automatically assigns this status to the contract when the contract is paid off (through the Payoff update) with an activity status of ‘NVOL'' (suspended earnings repossession).', NULL),
  ('ls_status', 'NDSC', 'CONTRACT DISCOUNTING, the contract has been discounted through the Contract Discounting update. The contract Discounting update is used to discount contract payment streams which are then sold to investors. System automatically assigns this status to the contract when discounted.', NULL),
  ('ls_status', 'NHLD', 'SUSPENDED EARNINGS HOLD, the income earnings are suspended for the contract for a non-specific reason. This status is entered through either the Suspended earnings update.', NULL),
  ('ls_status', 'NINS', 'SUSPENDED EARNINGS NON-INSURANCE, the income earnings are suspended for the contract due to lack of adequate and/or required insurance. This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'NH01', 'SUSPENDED EARNINGS: FORECLOSURE, the income earnings are suspended for the contract due to foreclosure. The status is entered through the Suspended Earnings update.', NULL),
  ('ls_status', 'NH02', 'SUSPENDED EARNINGS: INSURANCE CLAIM, the income earnings are suspended for the contract due to pending insurance claim reasons. This status is entered through the Suspended Earnings update.', NULL),
  ('ls_status', 'NH03', 'SUSPENDED EARNINGS: SETTLEMENT, the income earnings are suspended for the contract due to pending settlement reasons. This status is entered through the Suspended Earnings update.', NULL),
  ('ls_status', 'NH04', 'SUSPENDED EARNINGS:WRITE OFF, the income earnings are suspended for the contract due to pending write off reasons. This status is entered through the Suspended Earnings update.', NULL),
  ('ls_status', 'NMAT', 'ACTIVE MATURED, the contract has matured. System automatically assigns this status to the contract when all the income for the contract has been earned.', NULL),
  ('ls_status', 'NPDS', 'PAID OFF: DISCOUNTED, the contract was paid off after discounted. The contract is no longer active. System automatically assigns this status to the contract when it is paid off through the Payoff update with an activity status of ‘NDSC'' (Contract Discounting).', NULL),
  ('ls_status', 'NPER', 'PAID OFF: EARLY, the contract was paid off or terminated before maturity. The contract is no longer active. System automatically assigns this status to the contract when it is paid off or terminated through the Payoff update with an activity status beginning with an ‘A'' (e.g., ‘ANOR'').', NULL),
  ('ls_status', 'NPHL', 'PAID OFF: SUSPENDED, this status is automatically assigned after paying off or terminating the contract with an activity status ‘NHLD'' (suspended earnings hold),', NULL),
  ('ls_status', 'NPMT', 'PAID OFF: MATURED, the contract was paid off or terminated at maturity. The contract is no longer active. System automatically assigns this status to the contract when it is paid off or terminated through the Payoff update with an activity status of ‘NMAT'' (active matured).', NULL),
  ('ls_status', 'NPRC', 'PAID OFF: RESCISSION, the contract was paid off or terminated because the obligor rescinded on the contract contract. The contract is no longer active. System automatically assigns this status to the contract when it is paid off or terminated through the Payoff update with an activity status of ‘NREC'' (suspended earnings rescission).', NULL),
  ('ls_status', 'NPST', 'PAID OFF: INSURANCE SETTLEMENT, the contract was paid off or terminated by an insurance settlement. The contract is no longer active. System automatically assigns this status to the contract when it is paid off or terminated through the Payoff update with an activity status of ‘NINS'' (suspended earnings non-insurance) or ‘NSET'' (suspended earnings insurance settlement).', NULL),
  ('ls_status', 'NP02', 'PAID OFF: INSURANCE CLAIM, the contract was paid off or terminated by an insurance claim. The contract is no longer active. System automatically assigns this status to the contract when it is paid off or terminated through the Pay-off update with an activity status of ''NH02'' (suspended earnings insurance claim).', NULL),
  ('ls_status', 'NP03', 'PAID OFF: SETTLEMENT, the contract was paid off or terminated by a settlement. The contract is no longer active. System automatically assigns this status to the contract when it is paid off or terminated through the Payoff update with an activity status of ‘NH03'' (suspended earnings set-tlement).', NULL),
  ('ls_status', 'NREC', 'SUSPENDED EARNINGS RESCISSION, the income earnings are suspended for the contract because the obligor has rescinded on the contract. This status is entered through the Suspended Earnings update.', NULL),
  ('ls_status', 'NSET', 'SUSPENDED EARNINGS INSURANCE SETTLEMENT, the income earnings are suspended for the contract because an insurance settlement is pending (i.e., the assets have been damaged or destroyed). This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'NSKP', 'SUSPENDED EARNINGS SKIP, the income earnings are suspended for the contract because the obligor absconded with the financed assets. This status is entered through the Suspended earnings update.', NULL),
  ('ls_status', 'NVOL', 'SUSPENDED EARNINGS VOLUNTARY REPOSSESSION, the income earnings are suspended for the contract because the obligor desires to return the assets to the lender/lessor in order to terminate the contract. This status is entered through the Suspended earnings update.', NULL),
  ('asset_status', 'NLSE', 'NEW ON LEASE', 'The asset is currently on lease. LeasePak automatically assigns this status to the asset when it is booked to a lease through the Book Lease option of the New Lease update [U0101], the Rebook update [U0116], or the Asset Add-on update [U0113].'),
  ('asset_status', 'ULSE', 'USED ON LEASE', 'The asset is currently on lease. LeasePak automatically assigns this status to the asset when it is booked to a lease through the Book Lease option of the New Lease update [U0101], the Rebook update [U0116], or the Asset Add-on update [U0113].'),
  ('asset_status', 'NRIN', 'NEW IN INVENTORY', 'The asset is currently in inventory. LeasePak automatically assigns this status to the asset when it is returned to inventory through the Rebook update [U0116] or the Termination option of the Payoff update [U0103]. This status is also assigned to the asset if a disbursement to pay the vendor for the cost of the asset is made (through the Check Disbursal option of the New Lease update [U0101].'),
  ('asset_status', 'URIN', 'USED IN INVENTORY', 'The asset is currently in inventory. LeasePak automatically assigns this status to the asset when it is returned to inventory through the Rebook update [U0116] or the Termination option of the Payoff update [U0103]. This status is also assigned to the asset if a disbursement to pay the vendor for the cost of the asset is made (through the Check Disbursal option of the New Lease update [U0101].'),
  ('asset_status', 'NRIV', 'NEW PRE INVENTORY', 'The asset is newly entered into inventory. Only assets with this status may be deleted from inventory using the Delete Asset option of the New Lease update [U0101]. LeasePak automatically assigns this status to the asset when it is placed in inventory through the Add Asset option of the New Lease update [U0101].'),
  ('asset_status', 'URIV', 'USED PRE INVENTORY', 'The asset is newly entered into inventory. Only assets with this status may be deleted from inventory using the Delete Asset option of the New Lease update [U0101]. LeasePak automatically assigns this status to the asset when it is placed in inventory through the Add Asset option of the New Lease update [U0101].'),
  ('asset_status', 'NRPR', 'NEW IN REPAIR', 'The asset is in repair. This status is reserved for future system use.'),
  ('asset_status', 'URPR', 'USED IN REPAIR', 'The asset is in repair. This status is reserved for future system use.'),
  ('asset_status', 'NRPS', 'NEW REPOSSESSED', 'The asset is repossessed. This status is reserved for future system use.'),
  ('asset_status', 'URPS', 'USED REPOSSESSED', 'The asset is repossessed. This status is reserved for future system use.'),
  ('asset_status', 'NRSL', 'NEW FOR SALE', 'The asset is being held for a pending sale. This status is reserved for future system use.'),
  ('asset_status', 'URSL', 'USED FOR SALE', 'The asset is being held for a pending sale. This status is reserved for future system use.'),
  ('asset_status', 'NSLD', 'NEW ASSET SOLD', 'The asset has been sold. LeasePak automatically assigns this status to the asset when it is sold through the Payoff option (lease or asset payoff) or the Sale of Asset in Inventory option of the Payoff update [U0103].'),
  ('asset_status', 'USLD', 'USED ASSET SOLD', 'The asset has been sold. LeasePak automatically assigns this status to the asset when it is sold through the Payoff option (lease or asset payoff) or the Sale of Asset in Inventory option of the Payoff update [U0103].'),
  ('ls_type', 'CSA', 'Conditional Sales Agreement, A form of sales contract in which the seller reserves title to the goods until the buyer completes all payments for the goods and fulfills all conditions of the contract. After payment has been concluded, the title to the goods passes to the buyer. Note: CSA is a form of chattel paper.', NULL),
  ('ls_type', 'FIN', 'Finance leases, a financed or “true lease” that generally has a meaningful residual value booked.  The lessor is typically the tax owner of the asset(s).', NULL),
  ('ls_type', 'INSL', 'Installment loan, a loan or a promissory note.', NULL),
